# c360: 다리 난간은 물 위에만 (길 위로 뚫고 들어오지 않게)
C360_R = [('      if (x1 - x0 >= z1 - z0) for (const z of [z0 + 0.25, z1 - 0.25]) flat(x1 - x0, 0.5, (x0 + x1) / 2, z, railMat, -0.89);\n      else for (const x of [x0 + 0.25, x1 - 0.25]) flat(0.5, z1 - z0, x, (z0 + z1) / 2, railMat, -0.89);', '      const along = x1 - x0 >= z1 - z0, W = CH_MAP.rivers.filter((r) => along ? r[1] <= z1 + 0.1 && r[3] >= z0 - 0.1 && r[0] < x1 && r[2] > x0 : r[0] <= x1 + 0.1 && r[2] >= x0 - 0.1 && r[1] < z1 && r[3] > z0);   /* c360: 난간은 물 위에만 — 다리 끝이 길 위로 들어가도 난간이 길을 뚫지 않게 */\n      const a0 = W.length ? Math.max(along ? x0 : z0, Math.min(...W.map((r) => along ? r[0] : r[1]))) : along ? x0 : z0, a1 = W.length ? Math.min(along ? x1 : z1, Math.max(...W.map((r) => along ? r[2] : r[3]))) : along ? x1 : z1;\n      if (along) for (const z of [z0 + 0.25, z1 - 0.25]) flat(a1 - a0, 0.5, (a0 + a1) / 2, z, railMat, -0.89);\n      else for (const x of [x0 + 0.25, x1 - 0.25]) flat(0.5, a1 - a0, x, (a0 + a1) / 2, railMat, -0.89);')]
